/* Task 14: the flesh correction against Kodak's fcn.10270280 at x87 PC53 (vectors/flesh_truth.pkv,
 * lab/vectors/gen_flesh_truth.py, lab/rollbal/truth/t14). For every scene of every truth roll the test rebuilds the
 * image Kodak measured from the lo-res frame -- real frames from analysis_r4.pkv / analysis_r2.pkv, crafted ones
 * regenerated by synframe.c -- through pkc_analysis_image (Kodak's scpPre image, FNV) and pkc_scplut_apply with the
 * LUT Kodak applied (its flesh input, FNV), then runs pkc_flesh_delta with Kodak's pre-flesh triple and the exposure
 * pkc_sba_exposure_stops computes from Kodak's triple Y word of the same scene (Task 18, exposure_truth.pkv; = Kodak's
 * arg7 bit for bit; runs whose bp file stored arg7 itself keep the stored value) and compares the total and every result
 * Kodak wrote (the six result doubles bit for bit, the adjust words, fleshCount, stat, maxProb, the borders) plus the weight
 * plane and the pre-passed colour planes (FNV). */
#include "greatest.h"
#include "pkv.h"
#include "synframe.h"
#include "analysis/flesh.h"
#include "analysis/image.h"
#include "analysis/scplut.h"
#include "analysis/exposure.h"
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

static const int32_t *i32(const pkv_array *a) { return (const int32_t *)a->data; }
static const double *f64(const pkv_array *a) { return (const double *)a->data; }
static const uint8_t *u8(const pkv_array *a) { return (const uint8_t *)a->data; }
static int same_double(double a, double b) { return (isnan(a) && isnan(b)) || memcmp(&a, &b, sizeof a) == 0; }

static uint64_t fnv_init(void) { return 0xcbf29ce484222325ull; }
static uint64_t fnv_i16(uint64_t h, const int16_t *p, size_t n) {
    for (size_t i = 0; i < n; i++) {
        uint16_t v = (uint16_t)p[i];
        h ^= v & 0xff; h *= 0x100000001b3ull; h ^= v >> 8; h *= 0x100000001b3ull;
    }
    return h;
}
static uint64_t fnv_planes(const pkc_planes *P) {
    uint64_t h = fnv_init();
    for (int c = 0; c < 3; c++) h = fnv_i16(h, P->p[c], (size_t)P->w * P->h);
    return h;
}
static uint64_t le64(const uint8_t *b) { uint64_t v = 0; for (int i = 7; i >= 0; i--) v = v << 8 | b[i]; return v; }

static pkv_file *T, *A4, *A2, *X;
static pkc_flesh_params SHIPPED;
static pkc_sba_ctx CTX;

/* an entry's array; a missing one is a broken vector file: stop loudly rather than dereference NULL */
static const pkv_array *get(const char *fmt, int e) {
    char nm[64]; snprintf(nm, sizeof nm, fmt, e);
    const pkv_array *a = pkv_get(T, nm);
    if (!a) { fprintf(stderr, "flesh_truth.pkv has no %s\n", nm); exit(2); }
    return a;
}

/* the lo-res frame of an entry's scene: planar u16, malloc'd */
static int frame_of(const int32_t *src, uint16_t **lo, int *w, int *h) {
    if (src[0] == 0) {
        pkv_file *A = src[1] == 4 ? A4 : A2;
        char nm[32]; snprintf(nm, sizeof nm, "f%d_lo", src[2]);
        const pkv_array *a = pkv_get(A, nm);
        if (!a) return -1;
        *h = a->dims[1]; *w = a->dims[2];
        *lo = malloc(a->n * sizeof **lo);
        if (!*lo) return -1;
        memcpy(*lo, a->data, a->n * sizeof **lo);
        return 0;
    }
    if (src[0] == 1) return synframe_numpy(f64(pkv_get(T, "npar")) + (size_t)src[1] * 20, lo, w, h);
    const pkv_array *R = pkv_get(T, "recipe");
    return synframe_recipe(i32(R) + (size_t)src[1] * R->dims[1], i32(pkv_get(T, "recipe_len"))[src[1]], lo, w, h);
}

/* params equal to Kodak's dump (e<i>_pard / pari / tab) */
static int params_equal(const pkc_flesh_params *p, int e, char *msg, size_t cap) {
    const double *d = f64(get("e%d_pard", e)), *t = f64(get("e%d_tab", e));
    const int32_t *q = i32(get("e%d_pari", e));
    double pd[15] = { p->axial_prob, p->clip_amount, p->lscale, p->sscale, p->tscale, p->grow_threshold,
                      p->region_threshold, p->beta, p->front_lit_beta, p->back_lit_beta, p->flesh_pref_adj,
                      p->flesh_neutral_aim, p->flesh_count_thresh, p->percent_flesh_adj, p->exposure_limit };
    int32_t pi[10] = { p->loff, p->soff, p->toff, p->use_advanced, p->st_only, p->t_space, p->one_d_table,
                       p->write_intermediate_images, p->use_small_analysis_image, p->darken_only };
    for (int j = 0; j < 15; j++) if (!same_double(pd[j], d[j])) { snprintf(msg, cap, "e%d: dpi double %d %.17g, Kodak %.17g", e, j, pd[j], d[j]); return 0; }
    for (int j = 0; j < 10; j++) if (pi[j] != q[j]) { snprintf(msg, cap, "e%d: dpi int %d %d, Kodak %d", e, j, pi[j], q[j]); return 0; }
    for (int j = 0; j < 32; j++)
        if (!same_double(p->cond_l[j], t[j]) || !same_double(p->cond_s[j], t[32 + j]) || !same_double(p->cond_t[j], t[64 + j])) {
            snprintf(msg, cap, "e%d: condProb tables differ at bin %d", e, j); return 0;
        }
    return 1;
}

/* an edited dpi run: the dpi text from the vector, read through pkc_flesh_params_read with the shipped tables */
static pk_status params_of_text(int row, pkc_flesh_params *p) {
    const pkv_array *D = pkv_get(T, "dpitext");
    char path[] = "/tmp/pk_flesh_dpi_XXXXXX";
    int fd = mkstemp(path);
    if (fd < 0) return PK_E_IO;
    const char *txt = (const char *)u8(D) + (size_t)row * D->dims[1];
    size_t len = strnlen(txt, (size_t)D->dims[1]);
    ssize_t wr = write(fd, txt, len);
    close(fd);
    pk_status st = wr == (ssize_t)len ? pkc_flesh_params_read(path, VENDOR_ROOT "/anselinstalldir/dataPathItems/flesh/CondProbTables", p) : PK_E_IO;
    unlink(path);
    return st;
}

/* arg7 for scene k of entry e: the exposure pkc_sba_exposure_stops computes from the sba instance's triple Y word of the
 * same job (exposure_truth.pkv f<e>_run), which must be Kodak's arg7 bit for bit; Kodak's (stored) arg7 when the Task 14
 * run stored it (f<e>_run = -1). 0 on success. */
static int exposure_of(int e, int k, float *expo, char *msg, size_t cap) {
    char nm[32];
    int32_t ebits = i32(get("e%d_expo", e))[k];
    snprintf(nm, sizeof nm, "f%d_run", e);
    const pkv_array *R = pkv_get(X, nm);
    if (!R || R->dtype != 4) { snprintf(msg, cap, "e%d: no exposure run", e); return 1; }
    int run = i32(R)[0];
    if (run < 0) { memcpy(expo, &ebits, sizeof *expo); return 0; }
    snprintf(nm, sizeof nm, "e%d_y", run);
    const pkv_array *Y = pkv_get(X, nm);
    if (!Y || Y->dtype != 4 || (int)Y->n <= k) { snprintf(msg, cap, "e%d s%d: no triple Y word", e, k); return 1; }
    pkc_sba_triple_out t; memset(&t, 0, sizeof t);
    t.triple[0] = i32(Y)[k];
    double st;
    if (pkc_sba_exposure_stops(&t, &CTX, &st) != PK_OK) { snprintf(msg, cap, "e%d s%d: exposure", e, k); return 1; }
    *expo = (float)st;
    if (memcmp(expo, &ebits, sizeof *expo)) { snprintf(msg, cap, "e%d s%d: exposure %g, Kodak's arg7 %08x", e, k, st, (unsigned)ebits); return 1; }
    return 0;
}

/* one scene; 0 = Kodak's, else msg */
static int check_scene(int e, int k, const pkc_flesh_params *p, char *msg, size_t cap) {
    const int32_t *src = i32(get("e%d_src", e)) + 4 * k, *dims = i32(get("e%d_dims", e)) + 2 * k;
    const uint8_t *fnv = u8(get("e%d_fnv", e)) + 16 * k, *pf = u8(get("e%d_pfnv", e)) + 40 * k;
    const int16_t *pre = (const int16_t *)get("e%d_pre", e)->data + 3 * k, *tot = (const int16_t *)get("e%d_tot", e)->data + 3 * k;
    const double *kr = f64(get("e%d_res", e)) + 7 * k;
    const int32_t *ki = i32(get("e%d_resi", e)) + 8 * k;
    float expo;
    if (exposure_of(e, k, &expo, msg, cap)) return 1;
    const pkv_array *L = pkv_get(T, "luts");
    const pkc_lut3 *lut = (const pkc_lut3 *)((const int16_t *)L->data + (size_t)i32(get("e%d_lut", e))[k] * 3 * 4096);
    uint16_t *lo = NULL; int w, h, bad = 0;
    if (frame_of(src, &lo, &w, &h)) { snprintf(msg, cap, "e%d s%d: no frame", e, k); return 1; }
    const uint16_t *pl[3] = { lo, lo + (size_t)w * h, lo + 2 * (size_t)w * h };
    pkc_planes img; memset(&img, 0, sizeof img);
    pk_status st = pkc_analysis_image(pl, w, h, &img);
    free(lo);
    if (st != PK_OK) { snprintf(msg, cap, "e%d s%d: analysis image %d", e, k, (int)st); return 1; }
    if (img.w != dims[0] || img.h != dims[1]) { snprintf(msg, cap, "e%d s%d: dims %dx%d, Kodak %dx%d", e, k, img.w, img.h, dims[0], dims[1]); bad = 1; }
    if (!bad && fnv_planes(&img) != le64(fnv)) { snprintf(msg, cap, "e%d s%d: analysis image differs from Kodak's scpPre", e, k); bad = 1; }
    if (!bad && (st = pkc_scplut_apply(lut, &img, &img)) != PK_OK) { snprintf(msg, cap, "e%d s%d: scplut_apply %d", e, k, (int)st); bad = 1; }
    if (!bad && fnv_planes(&img) != le64(fnv + 8)) { snprintf(msg, cap, "e%d s%d: scpLut image differs from Kodak's flesh input", e, k); bad = 1; }
    int16_t got[3] = { 0, 0, 0 }; pkc_flesh_result r; memset(&r, 0x5a, sizeof r);
    if (!bad && (st = pkc_flesh_delta(p, &img, pre, expo, got, &r)) != PK_OK) { snprintf(msg, cap, "e%d s%d: flesh %d", e, k, (int)st); bad = 1; }
    double gd[7] = { r.x, r.nsum, r.q, r.neg_d130, r.max_prob255, r.threshold, r.stat };
    for (int j = 0; j < 7 && !bad; j++)
        if (!same_double(gd[j], kr[j])) { snprintf(msg, cap, "e%d s%d: result double %d = %.17g, Kodak %.17g", e, k, j, gd[j], kr[j]); bad = 1; }
    int32_t gi[6] = { r.adjust[0], r.count, r.max_prob, r.b_outer, r.b_inner, r.any_flesh };
    int ran = ki[6];
    for (int j = 0; j < 6 && !bad; j++) {
        if (!ran && j >= 3) break;                  /* no reduction: Kodak's borders and flag are not dumped */
        if (gi[j] != ki[j]) { snprintf(msg, cap, "e%d s%d: result int %d = %d, Kodak %d", e, k, j, gi[j], ki[j]); bad = 1; }
    }
    if (!bad && (r.adjust[1] != r.adjust[0] || r.adjust[2] != r.adjust[0])) { snprintf(msg, cap, "e%d s%d: adjust words differ", e, k); bad = 1; }
    if (!bad && !ran && r.any_flesh) { snprintf(msg, cap, "e%d s%d: flesh found, Kodak found none", e, k); bad = 1; }
    for (int c = 0; c < 3 && !bad; c++)
        if (got[c] != tot[c]) { snprintf(msg, cap, "e%d s%d: total[%d] = %d, Kodak %d", e, k, c, got[c], tot[c]); bad = 1; }
    int16_t *wp = bad ? NULL : malloc((size_t)img.w * img.h * sizeof *wp);
    if (!bad && (!wp || pkc_flesh_weight_plane(p, img.h, img.w, wp) != PK_OK)) { snprintf(msg, cap, "e%d s%d: weight plane", e, k); bad = 1; }
    if (!bad) {
        /* fcn.10271bc0's map before the pad (every scene): the inner (rows - 2 br) x (cols - 2 bc) of the padded plane */
        const int32_t *wm = i32(get("e%d_wmap", e)) + 2 * k;
        int br = (img.h - wm[0]) / 2, bc = (img.w - wm[1]) / 2;
        uint64_t hw = fnv_init();
        for (int y = br; y < br + wm[0]; y++) hw = fnv_i16(hw, wp + (size_t)y * img.w + bc, (size_t)wm[1]);
        if (2 * br + wm[0] != img.h || 2 * bc + wm[1] != img.w || hw != le64(u8(get("e%d_wfnv", e)) + 8 * k)) {
            snprintf(msg, cap, "e%d s%d: weight map differs (%dx%d, map %dx%d)", e, k, img.w, img.h, wm[1], wm[0]); bad = 1;
        }
    }
    if (!bad && ran) {
        /* the padded weight plane and the pre-passed colour planes Kodak's reduction read */
        if (fnv_i16(fnv_init(), wp, (size_t)img.w * img.h) != le64(pf)) { snprintf(msg, cap, "e%d s%d: weight plane differs (%dx%d)", e, k, img.w, img.h); bad = 1; }
        for (int c = 0; c < 3 && !bad; c++) {
            for (size_t i = 0; i < (size_t)img.w * img.h; i++) {
                int v = img.p[c][i] + pre[c];
                wp[i] = (int16_t)(v < 0 ? 0 : v > 4095 ? 4095 : v);
            }
            if (fnv_i16(fnv_init(), wp, (size_t)img.w * img.h) != le64(pf + 16 + 8 * c)) { snprintf(msg, cap, "e%d s%d: pre-pass plane %d differs", e, k, c); bad = 1; }
        }
    }
    free(wp);
    pkc_analysis_image_free(&img);
    return bad;
}

static int entry_count(void) {
    const pkv_array *E = pkv_get(T, "entries");
    int n = 1;
    for (size_t i = 0; i < E->n; i++) n += u8(E)[i] == ',';
    return n;
}
static void entry_name(int e, char *out, size_t cap) {
    const pkv_array *E = pkv_get(T, "entries");
    const char *s = (const char *)E->data; size_t n = E->n, i = 0;
    for (int k = 0; k < e && i < n; i++) if (s[i] == ',') k++;
    size_t j = 0;
    while (i < n && s[i] != ',' && j + 1 < cap) out[j++] = s[i++];
    out[j] = 0;
}

/* Every scene of every Kodak truth roll. */
TEST kodak_truth(void) {
    int n = entry_count(), bad = 0, nsc = 0, nfl = 0, ndelta = 0; char msg[256] = "", nm[32];
    for (int e = 0; e < n && !bad; e++) {
        int dpi = i32(get("e%d_dpi", e))[0];
        pkc_flesh_params p = SHIPPED;
        if (dpi) { pk_status st = params_of_text(dpi - 1, &p); if (st != PK_OK) { snprintf(msg, sizeof msg, "e%d: dpi %d read %d", e, dpi, (int)st); bad = 1; break; } }
        if (!params_equal(&p, e, msg, sizeof msg)) { bad = 1; break; }
        int ns = get("e%d_src", e)->dims[0];
        for (int k = 0; k < ns && !bad; k++) {
            bad = check_scene(e, k, &p, msg, sizeof msg);
            nsc++; nfl += i32(get("e%d_resi", e))[8 * k + 6]; ndelta += i32(get("e%d_resi", e))[8 * k] != 0;
        }
        if (bad) { entry_name(e, nm, sizeof nm); fprintf(stderr, "entry %s\n", nm); }
    }
    if (bad) FAILm(msg);
    printf("    kodak_truth: %d entries, %d scenes (%d with flesh, %d with a non-zero delta)\n", n, nsc, nfl, ndelta);
    PASS();
}

/* The port on scene k of entry e from its lo-res frame (analysis image, Kodak's LUT, Kodak's pre-flesh, the computed
 * exposure): delta and total. 0 on success. */
static int port_scene(int e, int k, const pkc_flesh_params *p, int16_t *delta, int16_t tot[3]) {
    const int32_t *src = i32(get("e%d_src", e)) + 4 * k;
    const int16_t *pre = (const int16_t *)get("e%d_pre", e)->data + 3 * k;
    char msg[128]; float expo;
    if (exposure_of(e, k, &expo, msg, sizeof msg)) { fprintf(stderr, "%s\n", msg); return 1; }
    const pkc_lut3 *lut = (const pkc_lut3 *)((const int16_t *)pkv_get(T, "luts")->data + (size_t)i32(get("e%d_lut", e))[k] * 3 * 4096);
    uint16_t *lo = NULL; int w, h;
    if (frame_of(src, &lo, &w, &h)) return 1;
    const uint16_t *pl[3] = { lo, lo + (size_t)w * h, lo + 2 * (size_t)w * h };
    pkc_planes img; memset(&img, 0, sizeof img);
    pk_status st = pkc_analysis_image(pl, w, h, &img);
    free(lo);
    if (st != PK_OK) return 1;
    pkc_flesh_result r; memset(&r, 0, sizeof r);
    st = pkc_scplut_apply(lut, &img, &img);
    if (st == PK_OK) st = pkc_flesh_delta(p, &img, pre, expo, tot, &r);
    pkc_analysis_image_free(&img);
    *delta = r.adjust[0];
    return st != PK_OK;
}

/* RE 16 section 3's numbers (the brief's), computed by the port from the lo-res frames: r4 on v1's film base -- delta
 * +18 / -28 / -8 / -39, totals 810 / 358 / 146 ... -- and what the pipeline's Kodak film base gives instead (r4: +19 / -28
 * / -6 / -39). */
TEST brief_numbers(void) {
    int n = entry_count(), seen = 0; char nm[32];
    static const int16_t v1d[4] = { 18, -28, -8, -39 }, v1t[4][3] = { { 810, 358, 146 }, { 901, 457, 227 }, { 1006, 561, 354 }, { 623, 198, 3 } };
    static const int16_t kd[4] = { 19, -28, -6, -39 }, kt[4][3] = { { 811, 359, 147 }, { 902, 457, 226 }, { 1009, 563, 355 }, { 623, 198, 3 } };
    for (int e = 0; e < n; e++) {
        entry_name(e, nm, sizeof nm);
        int v1 = !strcmp(nm, "r4v1"), k4 = !strcmp(nm, "r4");
        if (!v1 && !k4) continue;
        seen++;
        for (int k = 0; k < 4; k++) {
            int16_t d, tot[3];
            ASSERT_EQ(0, port_scene(e, k, &SHIPPED, &d, tot));
            ASSERT_EQ(v1 ? v1d[k] : kd[k], d);
            for (int c = 0; c < 3; c++) ASSERT_EQ(v1 ? v1t[k][c] : kt[k][c], tot[c]);
        }
    }
    ASSERT_EQ(2, seen);
    PASS();
}

/* The shipped dpi reaches the port as Kodak loaded it (every entry that ran it). */
TEST params_load(void) {
    pkc_flesh_params p;
    ASSERT_EQ(PK_OK, pkc_flesh_params_load(VENDOR_ROOT, &p));
    char msg[200];
    if (!params_equal(&p, 0, msg, sizeof msg)) FAILm(msg);
    ASSERT_EQ(PK_E_ARG, pkc_flesh_params_load(NULL, &p));
    ASSERT_EQ(PK_E_ARG, pkc_flesh_params_load(VENDOR_ROOT, NULL));
    ASSERT_EQ(PK_E_VENDOR_DATA, pkc_flesh_params_load("/nonexistent", &p));
    /* the DIGITAL_CAMERA dpi selects useAdvanced / the 3-D LUT / the small analysis image: not ported */
    ASSERT_EQ(PK_E_UNSUPPORTED, pkc_flesh_params_read(VENDOR_ROOT "/anselinstalldir/dataPathItems/flesh/FleshDPI/flesh-srcType-metric-DIGITAL_CAMERA-ANS_ROM12.dpi",
                                                      VENDOR_ROOT "/anselinstalldir/dataPathItems/flesh/CondProbTables", &p));
    PASS();
}

/* write text to a temp file; the caller unlinks */
static int tmp_text(char *path, const char *txt) {
    int fd = mkstemp(path);
    if (fd < 0) return -1;
    size_t n = strlen(txt);
    int ok = write(fd, txt, n) == (ssize_t)n;
    close(fd);
    return ok ? 0 : -1;
}
#define TABLES VENDOR_ROOT "/anselinstalldir/dataPathItems/flesh/CondProbTables"
#define SHIPPED_DPI VENDOR_ROOT "/anselinstalldir/dataPathItems/flesh/FleshDPI/flesh-srcType-metric-default-default.dpi"

/* the shipped dpi with key `key` given `val` (NULL: the line dropped) */
static pk_status read_edited(const char *key, const char *val, pkc_flesh_params *p) {
    FILE *f = fopen(SHIPPED_DPI, "rb");
    if (!f) return PK_E_IO;
    char txt[8192] = "", line[512];
    while (fgets(line, sizeof line, f)) {
        size_t kl = strlen(key);
        if (!strncmp(line, key, kl) && (line[kl] == ' ' || line[kl] == '=')) {
            if (val) { strcat(txt, key); strcat(txt, " = "); strcat(txt, val); strcat(txt, "\n"); }
        } else strcat(txt, line);
    }
    fclose(f);
    char path[] = "/tmp/pk_flesh_ed_XXXXXX";
    if (tmp_text(path, txt)) return PK_E_IO;
    pk_status st = pkc_flesh_params_read(path, TABLES, p);
    unlink(path);
    return st;
}

/* What the loader rejects, and why (flesh.h). */
TEST loader_errors(void) {
    pkc_flesh_params p;
    ASSERT_EQ(PK_E_ARG, pkc_flesh_params_read(NULL, TABLES, &p));
    ASSERT_EQ(PK_E_ARG, pkc_flesh_params_read(SHIPPED_DPI, NULL, &p));
    ASSERT_EQ(PK_E_ARG, pkc_flesh_params_read(SHIPPED_DPI, TABLES, NULL));
    ASSERT_EQ(PK_E_VENDOR_DATA, pkc_flesh_params_read(SHIPPED_DPI, "/nonexistent", &p));
    ASSERT_EQ(PK_OK, read_edited("darkenOnly", "7", &p));            /* an int stored as (v != 0) */
    ASSERT_EQ(1, p.darken_only);
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("fleshNeutralAim", NULL, &p));     /* a missing key */
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("loff", "40000", &p));             /* %hd range */
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("loff", "1.5", &p));
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("lscale", "abc", &p));
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("axialProb", "0", &p));            /* the weight map fails */
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("axialProb", "1", &p));
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("axialProb", "1.5", &p));
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("sCondProbKey", "condProbTbl-missing.tbl", &p));
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("sCondProbKey", "../FleshDPI/skinSBA.bn", &p));
    /* values that would make the port (and Kodak) read or write outside its buffers */
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("clipAmount", "-0.30", &p));       /* negative borders */
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("clipAmount", "1.0", &p));         /* sigma 0 */
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("clipAmount", "1.5", &p));
    ASSERT_EQ(PK_OK, read_edited("clipAmount", "0", &p));                       /* loads; pkc_flesh_delta refuses it */
    ASSERT_EQ(PK_OK, read_edited("clipAmount", "0.99", &p));
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("sscale", "-0.001", &p));          /* a negative axis index */
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("sscale", "0", &p));
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("sscale", "0.000001", &p));        /* v / scale beyond int32 */
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("lscale", "0.00002", &p));
    ASSERT_EQ(PK_OK, read_edited("lscale", "0.000021", &p));                   /* 45053 / scale just below 2^31 */
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("tscale", "-30", &p));
    ASSERT_EQ(PK_E_VENDOR_DATA, read_edited("tscale", "1e-50", &p));           /* float32 narrowing to 0 */
    ASSERT_EQ(PK_E_UNSUPPORTED, read_edited("useAdvanced", "1", &p));          /* the unported branches */
    ASSERT_EQ(PK_E_UNSUPPORTED, read_edited("oneDTable", "0", &p));
    ASSERT_EQ(PK_E_UNSUPPORTED, read_edited("useSmallAnalysisImage", "1", &p));
    /* a table that is not 32 values */
    char dir[] = "/tmp/pk_flesh_tabXXXXXX";
    ASSERT(mkdtemp(dir));
    char tp[600], txt[2000] = "size = 32\nvals =\n";
    for (int i = 0; i < 31; i++) strcat(txt, " 0.5");
    snprintf(tp, sizeof tp, "%s/condProbTbl-s.tbl", dir);
    FILE *f = fopen(tp, "w"); ASSERT(f); fputs(txt, f); fclose(f);
    for (const char *n = "lt"; *n; n++) {               /* the other two tables: copies of the shipped ones */
        char a[600], b[600];
        snprintf(a, sizeof a, TABLES "/condProbTbl-%c.tbl", *n); snprintf(b, sizeof b, "%s/condProbTbl-%c.tbl", dir, *n);
        FILE *in = fopen(a, "rb"), *out = fopen(b, "wb"); ASSERT(in && out);
        int c; while ((c = fgetc(in)) != EOF) fputc(c, out);
        fclose(in); fclose(out);
    }
    ASSERT_EQ(PK_E_VENDOR_DATA, pkc_flesh_params_read(SHIPPED_DPI, dir, &p));
    f = fopen(tp, "w"); ASSERT(f); fputs("size = 31\nvals =\n", f); for (int i = 0; i < 31; i++) fputs(" 0.5", f); fclose(f);
    ASSERT_EQ(PK_E_VENDOR_DATA, pkc_flesh_params_read(SHIPPED_DPI, dir, &p));
    f = fopen(tp, "w"); ASSERT(f); fputs("size = 32\nvals =\n", f); for (int i = 0; i < 32; i++) fputs(" 0.25", f); fclose(f);
    ASSERT_EQ(PK_OK, pkc_flesh_params_read(SHIPPED_DPI, dir, &p));
    ASSERT_EQ(0.25, p.cond_s[31]);
    for (const char *n = "lst"; *n; n++) { snprintf(tp, sizeof tp, "%s/condProbTbl-%c.tbl", dir, *n); unlink(tp); }
    rmdir(dir);
    PASS();
}

/* Arguments, and inputs the port refuses (flesh.h). */
TEST bad_args(void) {
    int w = 120, h = 120; size_t n = (size_t)w * h;
    int16_t *buf = calloc(3 * n, sizeof *buf); ASSERT(buf);
    for (size_t i = 0; i < 3 * n; i++) buf[i] = 1200;
    pkc_planes img = { w, h, { buf, buf + n, buf + 2 * n } };
    int16_t pre[3] = { 0, 0, 0 }, tot[3] = { 7, 7, 7 };
    pkc_flesh_result r;
    ASSERT_EQ(PK_OK, pkc_flesh_delta(&SHIPPED, &img, pre, 0.0f, tot, NULL));     /* res may be NULL */
    ASSERT_EQ(0, tot[0]);
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(NULL, &img, pre, 0.0f, tot, &r));
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(&SHIPPED, NULL, pre, 0.0f, tot, &r));
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(&SHIPPED, &img, NULL, 0.0f, tot, &r));
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(&SHIPPED, &img, pre, 0.0f, NULL, &r));
    pkc_flesh_params q = SHIPPED; q.use_advanced = 1;
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(&q, &img, pre, 0.0f, tot, &r));
    q = SHIPPED; q.axial_prob = 1.0;
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(&q, &img, pre, 0.0f, tot, &r));
    pkc_planes tiny = { 2, 120, { buf, buf + n, buf + 2 * n } };
    ASSERT_EQ(PK_E_IMAGE_TOO_SMALL, pkc_flesh_delta(&SHIPPED, &tiny, pre, 0.0f, tot, &r));
    q = SHIPPED; q.clip_amount = 0.01;                  /* row border 0: Kodak's loop would start past the image */
    ASSERT_EQ(PK_E_IMAGE_TOO_SMALL, pkc_flesh_delta(&q, &img, pre, 0.0f, tot, &r));
    q = SHIPPED; q.clip_amount = -0.3;                  /* hand-built params the loader refuses */
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(&q, &img, pre, 0.0f, tot, &r));
    q = SHIPPED; q.sscale = 1e-6;
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(&q, &img, pre, 0.0f, tot, &r));
    q = SHIPPED; q.tscale = -1.0;
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(&q, &img, pre, 0.0f, tot, &r));
    pkc_planes noplane = { w, h, { buf, NULL, buf } };
    ASSERT_EQ(PK_E_ARG, pkc_flesh_delta(&SHIPPED, &noplane, pre, 0.0f, tot, &r));
    /* samples outside 0..4095 index the shift LUT clamped (Kodak reads outside it); no crash, a result */
    buf[0] = -5; buf[1] = 5000;
    ASSERT_EQ(PK_OK, pkc_flesh_delta(&SHIPPED, &img, pre, 0.0f, tot, &r));
    int16_t *wp = malloc(n * sizeof *wp); ASSERT(wp);
    ASSERT_EQ(PK_E_ARG, pkc_flesh_weight_plane(NULL, h, w, wp));
    ASSERT_EQ(PK_E_ARG, pkc_flesh_weight_plane(&SHIPPED, 0, w, wp));
    ASSERT_EQ(PK_E_ARG, pkc_flesh_weight_plane(&SHIPPED, h, 40000, wp));
    ASSERT_EQ(PK_E_ARG, pkc_flesh_weight_plane(&SHIPPED, h, w, NULL));
    q = SHIPPED; q.clip_amount = -0.3;                  /* would write outside out (2299 words each side at 120 x 120) */
    ASSERT_EQ(PK_E_ARG, pkc_flesh_weight_plane(&q, h, w, wp));
    q = SHIPPED; q.clip_amount = 1.0;
    ASSERT_EQ(PK_E_ARG, pkc_flesh_weight_plane(&q, h, w, wp));
    ASSERT_EQ(PK_OK, pkc_flesh_weight_plane(&SHIPPED, h, w, wp));
    ASSERT_EQ(1000, wp[(h / 2) * w + w / 2]);           /* the peak at the centre */
    /* pkc_scplut_apply: arguments; in place and out of place agree; an out-of-range sample is clamped */
    pkc_lut3 *L = malloc(sizeof *L); ASSERT(L);
    for (int c = 0; c < 3; c++) for (int i = 0; i < 4096; i++) L->t[c][i] = (int16_t)(4095 - i);
    int16_t *ob = malloc(3 * n * sizeof *ob); ASSERT(ob);
    pkc_planes out = { 0, 0, { ob, ob + n, ob + 2 * n } };
    ASSERT_EQ(PK_E_ARG, pkc_scplut_apply(NULL, &img, &out));
    ASSERT_EQ(PK_E_ARG, pkc_scplut_apply(L, NULL, &out));
    ASSERT_EQ(PK_E_ARG, pkc_scplut_apply(L, &img, NULL));
    ASSERT_EQ(PK_E_ARG, pkc_scplut_apply(L, &noplane, &out));
    ASSERT_EQ(PK_OK, pkc_scplut_apply(L, &img, &out));
    ASSERT_EQ(w, out.w); ASSERT_EQ(h, out.h);
    ASSERT_EQ(4095, ob[0]); ASSERT_EQ(0, ob[1]); ASSERT_EQ(4095 - 1200, ob[2]);
    ASSERT_EQ(PK_OK, pkc_scplut_apply(L, &img, &img));
    ASSERT_MEM_EQ(ob, buf, 3 * n * sizeof *buf);
    free(L); free(ob); free(wp); free(buf);
    PASS();
}

GREATEST_MAIN_DEFS();
int main(int argc, char **argv) {
    GREATEST_MAIN_BEGIN();
    T = pkv_open(PKV_DIR "/flesh_truth.pkv"); A4 = pkv_open(PKV_DIR "/analysis_r4.pkv"); A2 = pkv_open(PKV_DIR "/analysis_r2.pkv");
    X = pkv_open(PKV_DIR "/exposure_truth.pkv");
    if (!T || !A4 || !A2 || !X) { fprintf(stderr, "cannot open the vectors\n"); return 1; }
    /* exposure_truth.pkv's flesh entries are this file's, in order */
    const pkv_array *E = pkv_get(T, "entries"), *XE = pkv_get(X, "flesh_entries");
    if (!E || !XE || E->n != XE->n || memcmp(E->data, XE->data, E->n)) { fprintf(stderr, "flesh entries differ\n"); return 1; }
    if (pkc_sba_ctx_load(VENDOR_ROOT, DERIVED_ROOT, &CTX) != PK_OK) { fprintf(stderr, "cannot load the SBA ctx\n"); return 1; }
    if (pkc_flesh_params_load(VENDOR_ROOT, &SHIPPED) != PK_OK) memset(&SHIPPED, 0, sizeof SHIPPED);
    RUN_TEST(params_load);
    RUN_TEST(loader_errors);
    RUN_TEST(bad_args);
    RUN_TEST(brief_numbers);
    RUN_TEST(kodak_truth);
    pkv_close(T); pkv_close(A4); pkv_close(A2); pkv_close(X); pkc_sba_ctx_free(&CTX);
    GREATEST_MAIN_END();
}
